// Six visitor turns that exercise every route.
// __force_bad_ai__ simulates an unparseable model answer so the failure
// branch runs without an API key.
const turns = [
  {
    question: 'What are your support hours?',
    visitor_email: 'user@example.com',
    session_id: 'demo-s1',
    sim: 'answerable',
  },
  {
    question: 'Do you offer SSO on the starter plan?',
    visitor_email: 'user@example.com',
    session_id: 'demo-s1',
    sim: 'gap',
  },
  {
    question: 'Interested in enterprise — reach me at user@example.com',
    visitor_email: '',
    session_id: 'demo-s2',
    sim: 'lead',
  },
  {
    question: '   ',
    visitor_email: 'user@example.com',
    session_id: 'demo-s3',
    sim: 'empty',
  },
  {
    question: 'Do you offer SSO on the starter plan?',
    visitor_email: 'user@example.com',
    session_id: 'demo-s1',
    sim: 'repeat',
  },
  {
    question: '__force_bad_ai__',
    visitor_email: 'user@example.com',
    session_id: 'demo-s3',
    sim: 'bad_ai',
  },
];

return turns.map((t) => ({ json: { ...t, origin: 'demo', live: false } }));

// Deterministic verdict mirroring the AI contract — the demo proves the
// routing without an OpenAI key. Production swaps this for
// "Answer from FAQ only" + "Parse AI verdict".

const FAQ = [
  { q: 'What are your support hours?', a: 'We reply within one business day, Monday to Friday 09:00-17:00 UTC.' },
  { q: 'How do I get a refund?', a: 'Email us with your order number and we refund within 14 days.' },
];

const EMAIL_RE = /[\w.+-]+@[\w-]+\.[\w.]{2,}/;
const seen = new Set();

function normalize(q) {
  return String(q || '').trim().toLowerCase();
}

return $input.all().map((item) => {
  const t = item.json;
  const q = normalize(t.question);

  if (!q) {
    return { json: { status: 'alerted', kind: 'missing-data', alert: 'Empty visitor message — nothing to answer or log', origin: 'demo', live: false } };
  }
  if (t.sim === 'bad_ai') {
    return { json: { status: 'alerted', kind: 'failure', alert: 'AI returned an unparseable verdict — question queued for owner review', origin: 'demo', live: false } };
  }
  if (seen.has(q)) {
    return { json: { status: 'alerted', kind: 'duplicate', alert: `Duplicate question in this session: "${t.question}"`, origin: 'demo', live: false } };
  }
  seen.add(q);

  const email = (t.question.match(EMAIL_RE) || [t.visitor_email])[0];
  if (email && (t.sim === 'lead' || !t.visitor_email)) {
    return { json: { status: 'logged', verdict: 'lead', question: t.question, lead_email: email, dest_tab: 'Leads', notify_subject: 'New lead from FAQ chat', reply: 'Thanks — a human will follow up shortly.', origin: 'demo', live: false } };
  }

  const hit = FAQ.find((f) => q.includes(normalize(f.q).split(' ').slice(1, 4).join(' ')));
  if (t.sim === 'answerable' || hit) {
    const answer = hit ? hit.a : 'Here is what our FAQ says on that.';
    return { json: { status: 'answered', verdict: 'answered', question: t.question, reply: answer, origin: 'demo', live: false } };
  }

  return { json: { status: 'logged', verdict: 'gap', question: t.question, dest_tab: 'Unanswered', notify_subject: 'Unanswered question in FAQ chat', reply: 'Good question — I do not have that yet. Leave your email and a human will follow up.', origin: 'demo', live: false } };
});

// Exactly one digest per run — fed by a single wave of demo items, so an
// empty branch can never starve it or multiply it.
const items = $input.all();
const alerts = items.filter((i) => i.json.status === 'alerted').map((i) => i.json.alert);
const ok = items.filter((i) => i.json.status && i.json.status !== 'alerted');

return [{
  json: {
    status: 'digest',
    summary: `Run complete: ${items.length} visitor turn(s) processed, ${alerts.length} alert(s)`,
    processed: ok.length,
    answered: ok.filter((i) => i.json.verdict === 'answered').length,
    gaps: ok.filter((i) => i.json.verdict === 'gap').length,
    leads: ok.filter((i) => i.json.verdict === 'lead').length,
    needs_attention: alerts,
  },
}];

// ⚙ Workflow Config — the only place you edit after setup.
// 1. Run "SETUP — press play on this node once" (Lane D) and copy the printed
//    spreadsheet_id into `sheet_id` below.
// 2. Put your owner email in `owner_email`.
// Every Google Sheets and Gmail node in lanes A and B reads from here —
// change it once, applies everywhere.
return [{
  json: {
    sheet_id: 'PASTE_SPREADSHEET_ID_HERE',
    owner_email: 'user@example.com',
  },
}];

// The Merge delivers one stream: the visitor's chat item plus one item per
// FAQ row. Build a single prompt carrying both.
const rows = $input.all();
const questionItem = rows.find((r) => r.json.chatInput !== undefined);
const faqRows = rows.filter((r) => r.json.q && r.json.a);

const faqText = faqRows.map((r) => `Q: ${r.json.q}\nA: ${r.json.a}`).join('\n\n');
const question = questionItem ? String(questionItem.json.chatInput) : '';
const visitorEmail = questionItem ? (questionItem.json.visitor_email || '') : '';

return [{
  json: {
    question,
    visitor_email: visitorEmail,
    session_id: questionItem ? questionItem.json.sessionId : '',
    origin: 'chat',
    live: true,
    messages: [
      {
        role: 'system',
        content:
          'You are the website FAQ assistant. Answer ONLY from the FAQ below. ' +
          'Reply as strict JSON: {"question": <the visitor question verbatim>, ' +
          '"answered": true|false, "reply": <one or two sentences>, ' +
          '"contact": <email or phone the visitor left in the message, else null>}. ' +
          'Keep the visitor question verbatim including any contact details. ' +
          'If the FAQ does not cover it, set answered=false and reply asking ' +
          'the visitor to leave their email so a human can follow up.\n\nFAQ:\n' + faqText,
      },
      { role: 'user', content: question },
    ],
  },
}];

// Turn the model's JSON verdict into a routed item. Unparseable output is a
// 'failure' alert — the bot never fabricates an answer.
const EMAIL_RE = /[\w.+-]+@[\w-]+\.[\w.]{2,}/;

return $input.all().map((item) => {
  const raw = (item.json.message && item.json.message.content) || '';
  let parsed;
  try {
    parsed = JSON.parse(String(raw).replace(/```json|```/g, '').trim());
  } catch (e) {
    parsed = null;
  }
  if (!parsed || typeof parsed.answered !== 'boolean') {
    return { json: { status: 'alerted', kind: 'failure', alert: 'AI returned an unparseable verdict — question queued for owner review', origin: 'chat', live: true } };
  }
  const question = String(parsed.question || '');
  const email = parsed.contact || (question.match(EMAIL_RE) || [null])[0];
  const base = { question, reply: String(parsed.reply || ''), origin: 'chat', live: true };
  if (parsed.answered) {
    return { json: { ...base, status: 'answered', verdict: 'answered' } };
  }
  if (email) {
    return { json: { ...base, status: 'logged', verdict: 'lead', lead_email: email, dest_tab: 'Leads', notify_subject: 'New lead from FAQ chat' } };
  }
  return { json: { ...base, status: 'logged', verdict: 'gap', dest_tab: 'Unanswered', notify_subject: 'Unanswered question in FAQ chat' } };
});

// Shape the visitor-facing reply (the hosted chat reads `output` from the
// last node — responseMode: lastNode).
return $input.all().map((item) => ({
  json: { ...item.json, output: item.json.reply || 'Thanks for your message.' },
}));

// Demo lane endpoint: record what the production write would do.
return $input.all().map((item) => ({
  json: {
    ...item.json,
    demo_note: `Would append to "${item.json.dest_tab}" and notify owner`,
  },
}));

// The error path does more than stop: alerts reach the digest AND the
// visitor still gets a graceful fallback (Reply to visitor synthesises the
// fallback text when `reply` is absent). Pass items through unchanged.
return $input.all();

// Weekly lane: group logged-but-unanswered questions, count frequency, and
// rank them — the questions asked most become this week's FAQ proposals.
const rows = $input.all();
const groups = {};
for (const row of rows) {
  const q = String(row.json.question || '').trim();
  if (!q) continue;
  const key = q.toLowerCase();
  groups[key] = groups[key] || { question: q, count: 0 };
  groups[key].count += Number(row.json.repeat_count || 1);
}
const ranked = Object.values(groups).sort((a, b) => b.count - a.count);
return [{ json: { gaps: ranked, gap_count: ranked.length } }];

