// One item per tab — `tab` routes it through the Switch; the remaining keys
// become that tab's columns (headers + an example row each).
return [
  { json: { tab: 'FAQ', q: 'What are your support hours?', a: 'We reply within one business day, Monday to Friday 09:00-17:00 UTC.' } },
  { json: { tab: 'FAQ', q: 'How do I get a refund?', a: 'Email us with your order number and we refund within 14 days.' } },
  { json: { tab: 'Unanswered', question: '(example) Do you offer SSO on the starter plan?', reply: 'Good question — I do not have that yet. Leave your email and a human will follow up.', session_id: 'example-session', asked_at: '2026-10-01T09:00:00.000Z', repeat_count: '1' } },
  { json: { tab: 'Leads', question: '(example) Interested in enterprise pricing', reply: 'Thanks — a human will follow up shortly.', lead_email: 'user@example.com', session_id: 'example-session', asked_at: '2026-10-01T09:05:00.000Z' } },
  { json: { tab: 'FAQ-Pending', proposed_q: '(example) Q: Do you offer a free trial? A: Yes — 14 days, no card required.', proposed_at: '2026-10-01T09:10:00.000Z' } },
];

// Terminal of the setup lane — prints the id to paste into the three
// Google Sheets nodes (documentId field on each).
const created = $('Create FAQ spreadsheet').first().json;
const sheetId = created.spreadsheetId || created.id || '';
return [{
  json: {
    spreadsheet_id: sheetId,
    spreadsheet_url: `https://docs.google.com/spreadsheets/d/${sheetId}`,
    next_step: 'Paste the spreadsheet_id into the Workflow Config node (one place, applies to every Sheets and Gmail node), set owner_email there too, then delete this setup lane.',
  },
}];
